(1, 1, 1, 4, '[PSA 10] 리자몽 ex SAR (SV2a 201/165)', '직접 한국판 포켓몬 151 박스를 개봉해 얻은 뒤 바로 PSA에 그레이딩을 접수한 원오너 소장품입니다.

