-- ───────────── 토론글 56건 (item_id = 품목 slug, 자유 토론은 NULL) ─────────────
INSERT INTO posts (id, user_id, board, tag, item_id, title, body, created_at, updated_at) VALUES
(1, 1, 'pokemon', 'analysis', 'charizard-ex-sar', NULL, 'PSA10 물량이 국내 유통 채널에서 눈에 띄게 줄어서 당분간 30만 원대 초반 지지선은 견고할 것 같아요.', UTC_TIMESTAMP() - INTERVAL 3600 MINUTE, UTC_TIMESTAMP() - INTERVAL 3600 MINUTE),
(2, 2, 'pokemon', 'qna', 'charizard-ex-sar', NULL, '지금 사면 고점일까요? 이번 주에만 4만 원 올랐네요.', UTC_TIMESTAMP() - INTERVAL 3480 MINUTE, UTC_TIMESTAMP() - INTERVAL 3480 MINUTE),
(3, 3, 'sneakers', 'poll', 'jordan-1-chicago', '조던 1 시카고 2015 OG vs 2022 로스트앤파운드, 어떤 것을 소장하시겠습니까?', '가성비 실착 vs 대장급 오리지널 소장가치 중 회원님들의 선택은?', UTC_TIMESTAMP() - INTERVAL 3360 MINUTE, UTC_TIMESTAMP() - INTERVAL 3360 MINUTE),
(4, 1, 'watch', 'qna', 'rolex-submariner', '서브마리너 풀세트 vs 단품, 리셀 시 차이 얼마나 나나요?', '보증서와 박스 유무에 따라 체결가 차이가 어느 정도인지 실거래 경험 공유 부탁드립니다.', UTC_TIMESTAMP() - INTERVAL 3240 MINUTE, UTC_TIMESTAMP() - INTERVAL 3240 MINUTE),
(5, 2, 'pokemon', 'analysis', 'charizard-ex-sar-sv2a-201', NULL, '일본판 SV2a 리자몽 PSA10, 이번 주 들어 5% 정도 빠졌네요. 한국판과 가격 차이가 좁혀지는 중입니다.', UTC_TIMESTAMP() - INTERVAL 3120 MINUTE, UTC_TIMESTAMP() - INTERVAL 3120 MINUTE),
(6, 3, 'pokemon', 'qna', 'charizard-ex-sar-sv2a-201', NULL, '일본판 vs 한국판, 장기 소장용이면 어느 쪽이 나을까요?', UTC_TIMESTAMP() - INTERVAL 3000 MINUTE, UTC_TIMESTAMP() - INTERVAL 3000 MINUTE),
(7, 1, 'pokemon', 'info', 'charizard-ex-sar-sv2a-201', NULL, 'PSA 접수 대행 이번 달 마감 일정 공유합니다. 일본판 SAR은 센터링 기준이 까다로우니 꼭 확인하고 보내세요.', UTC_TIMESTAMP() - INTERVAL 2880 MINUTE, UTC_TIMESTAMP() - INTERVAL 2880 MINUTE),
(8, 1, 'onepiece', 'analysis', 'luffy-gear5', NULL, '기어5 패러렐 시세가 3일째 18만 원에서 보합이네요. 신규 부스터 발매 전까지는 이 가격대 유지될 듯.', UTC_TIMESTAMP() - INTERVAL 2760 MINUTE, UTC_TIMESTAMP() - INTERVAL 2760 MINUTE),
(9, 3, 'free', 'info', 'blue-eyes-white-dragon', NULL, '쿼터 센츄리 크로니클 푸른 눈의 백룡 첫 거래가 9만 5천 원에 체결됐습니다.', UTC_TIMESTAMP() - INTERVAL 2640 MINUTE, UTC_TIMESTAMP() - INTERVAL 2640 MINUTE),
(10, 2, 'sneakers', 'verify', 'dunk-low-panda', NULL, '덩크 로우 범고래 정품 검수 포인트 정리했어요. 힐탭 자수 간격과 박스 라벨 폰트를 먼저 보세요.', UTC_TIMESTAMP() - INTERVAL 2520 MINUTE, UTC_TIMESTAMP() - INTERVAL 2520 MINUTE),
(11, 4, 'pokemon', 'analysis', 'charizard-ex-sar', NULL, '체결가 그래프 보면 2주 사이에 저점이 계속 올라오고 있어요. 32만 원 돌파 후 안착할지가 관건입니다.', UTC_TIMESTAMP() - INTERVAL 1800 MINUTE, UTC_TIMESTAMP() - INTERVAL 1800 MINUTE),
(12, 5, 'pokemon', 'qna', 'charizard-ex-sar', NULL, '처음 PSA 슬랩 사보려는데 실물 인증 사진에서 뭘 봐야 하나요?', UTC_TIMESTAMP() - INTERVAL 1200 MINUTE, UTC_TIMESTAMP() - INTERVAL 1200 MINUTE),
(13, 6, 'pokemon', 'analysis', 'charizard-ex-sar', NULL, '해외 시세는 오히려 내려가는 중이라 곧 조정 올 듯합니다. 이베이 최근 3일간 평균 낙찰가가 $210선까지 내려앉았어요.', UTC_TIMESTAMP() - INTERVAL 720 MINUTE, UTC_TIMESTAMP() - INTERVAL 720 MINUTE),
(14, 7, 'pokemon', 'unboxing', 'charizard-ex-sar', NULL, 'PSA 10 2장 수령했습니다. 홀로 결이 정말 예쁘네요. 감정 편차가 거의 없는 카드라 장기 보유 관점에서는 여전히 매력적이라고 봅니다.', UTC_TIMESTAMP() - INTERVAL 360 MINUTE, UTC_TIMESTAMP() - INTERVAL 360 MINUTE),
(15, 2, 'pokemon', 'poll', 'charizard-ex-sar', '리자몽 ex SAR 다음 주 시세 예상', '다음 주 리자몽 ex SAR PSA10 체결가, 어떻게 보시나요?', UTC_TIMESTAMP() - INTERVAL 180 MINUTE, UTC_TIMESTAMP() - INTERVAL 180 MINUTE),
(16, 4, 'pokemon', 'analysis', 'charizard-ex-sar-sv2a-201', NULL, '일본판은 해외 물량이 계속 들어와서 28만 원 근처에서 바닥 다지는 중으로 보입니다.', UTC_TIMESTAMP() - INTERVAL 1560 MINUTE, UTC_TIMESTAMP() - INTERVAL 1560 MINUTE),
(17, 6, 'pokemon', 'qna', 'charizard-ex-sar-sv2a-201', NULL, '일본판 PSA10을 한국판 가격에 팔려면 얼마나 기다려야 할까요?', UTC_TIMESTAMP() - INTERVAL 540 MINUTE, UTC_TIMESTAMP() - INTERVAL 540 MINUTE),
(18, 4, 'pokemon', 'analysis', 'mew-ex-sar-151', NULL, '뮤 ex SAR이 리자몽 따라서 천천히 오르고 있어요. 17만 원대 진입했습니다.', UTC_TIMESTAMP() - INTERVAL 2400 MINUTE, UTC_TIMESTAMP() - INTERVAL 2400 MINUTE),
(19, 5, 'pokemon', 'qna', 'mew-ex-sar-151', NULL, '뮤 SAR 센터링 좋은 개체 고르는 팁 있을까요?', UTC_TIMESTAMP() - INTERVAL 900 MINUTE, UTC_TIMESTAMP() - INTERVAL 900 MINUTE),
(20, 7, 'pokemon', 'analysis', 'umbreon-vmax-sa', NULL, '블래키 VMAX SA는 공급이 거의 없어서 140만 원대 후반이 새 지지선 같습니다.', UTC_TIMESTAMP() - INTERVAL 1980 MINUTE, UTC_TIMESTAMP() - INTERVAL 1980 MINUTE),
(21, 7, 'pokemon', 'unboxing', 'umbreon-vmax-sa', NULL, '드디어 블래키 SA PSA10 들였습니다. 실물이 사진보다 훨씬 좋네요.', UTC_TIMESTAMP() - INTERVAL 480 MINUTE, UTC_TIMESTAMP() - INTERVAL 480 MINUTE),
(22, 5, 'pokemon', 'qna', 'pikachu-ar-paldea', NULL, '피카츄 AR 3만 원이면 사도 될까요? 그레이딩 보낼 가치가 있을지 궁금합니다.', UTC_TIMESTAMP() - INTERVAL 1320 MINUTE, UTC_TIMESTAMP() - INTERVAL 1320 MINUTE),
(23, 10, 'onepiece', 'analysis', 'luffy-gear5', NULL, '기어5 패러렐은 대회 시즌 끝나면 수요가 줄어서 소폭 조정 올 수 있습니다.', UTC_TIMESTAMP() - INTERVAL 1680 MINUTE, UTC_TIMESTAMP() - INTERVAL 1680 MINUTE),
(24, 10, 'onepiece', 'unboxing', 'luffy-gear5', NULL, 'OP-05 한 박스 깠는데 기어5 패러렐 나왔습니다! 바로 슬리브 씌웠어요.', UTC_TIMESTAMP() - INTERVAL 300 MINUTE, UTC_TIMESTAMP() - INTERVAL 300 MINUTE),
(25, 10, 'onepiece', 'info', 'zoro-op01-parallel', NULL, 'OP-01 재판 소식이 있네요. 조로 패러렐 가격에 영향 있을지 지켜봐야겠습니다.', UTC_TIMESTAMP() - INTERVAL 2160 MINUTE, UTC_TIMESTAMP() - INTERVAL 2160 MINUTE),
(26, 6, 'onepiece', 'analysis', 'zoro-op01-parallel', NULL, '조로 패러렐은 재판 발표 이후에도 11만 원대 유지 중입니다. 수요가 탄탄해요.', UTC_TIMESTAMP() - INTERVAL 660 MINUTE, UTC_TIMESTAMP() - INTERVAL 660 MINUTE),
(27, 10, 'onepiece', 'analysis', 'shanks-op01-manga', NULL, '샹크스 코믹 패러렐은 고가 카드라 거래가 뜸하지만 체결될 때마다 조금씩 내려오는 중입니다.', UTC_TIMESTAMP() - INTERVAL 1860 MINUTE, UTC_TIMESTAMP() - INTERVAL 1860 MINUTE),
(28, 3, 'free', 'qna', 'dark-magician-girl-qccu', NULL, '블랙 매지션 걸 쿼터 센츄리판, 백룡보다 덜 오르는 이유가 뭘까요?', UTC_TIMESTAMP() - INTERVAL 1620 MINUTE, UTC_TIMESTAMP() - INTERVAL 1620 MINUTE),
(29, 7, 'free', 'analysis', 'blue-eyes-white-dragon', NULL, '백룡은 신규 팬 유입이 꾸준해서 9만 원대 중반은 지킬 것 같습니다.', UTC_TIMESTAMP() - INTERVAL 1080 MINUTE, UTC_TIMESTAMP() - INTERVAL 1080 MINUTE),
(30, 6, 'free', 'analysis', 'ohtani-topps-chrome-rc', NULL, '오타니 시즌 활약 덕에 루키 카드가 다시 90만 원대로 올라왔습니다.', UTC_TIMESTAMP() - INTERVAL 1440 MINUTE, UTC_TIMESTAMP() - INTERVAL 1440 MINUTE),
(31, 1, 'free', 'qna', 'son-heungmin-prizm', NULL, '손흥민 프리즘 실버, 그레이딩 보내면 얼마나 오를까요?', UTC_TIMESTAMP() - INTERVAL 960 MINUTE, UTC_TIMESTAMP() - INTERVAL 960 MINUTE),
(32, 8, 'sneakers', 'analysis', 'jordan-1-chicago', NULL, '시카고 OG는 새상품 매물이 줄면서 210만 원 선에서 거래되고 있습니다.', UTC_TIMESTAMP() - INTERVAL 2100 MINUTE, UTC_TIMESTAMP() - INTERVAL 2100 MINUTE),
(33, 8, 'sneakers', 'verify', 'jordan-4-military-black', NULL, '밀리터리 블랙 가품이 많이 돌아요. 텅 라벨 폰트와 힐 탭 각도를 꼭 비교하세요.', UTC_TIMESTAMP() - INTERVAL 1260 MINUTE, UTC_TIMESTAMP() - INTERVAL 1260 MINUTE),
(34, 2, 'sneakers', 'qna', 'jordan-4-military-black', NULL, '270 사이즈 28만 원대면 적당한 가격일까요?', UTC_TIMESTAMP() - INTERVAL 420 MINUTE, UTC_TIMESTAMP() - INTERVAL 420 MINUTE),
(35, 8, 'sneakers', 'analysis', 'travis-jordan-1-low-mocha', NULL, '트래비스 모카는 꾸준히 우상향입니다. 160만 원 돌파 시 추가 상승 예상합니다.', UTC_TIMESTAMP() - INTERVAL 1740 MINUTE, UTC_TIMESTAMP() - INTERVAL 1740 MINUTE),
(36, 3, 'sneakers', 'unboxing', 'travis-jordan-1-low-mocha', NULL, '모카 로우 정품 검수 통과 후 수령했습니다. 스우시 방향 확인 완료!', UTC_TIMESTAMP() - INTERVAL 240 MINUTE, UTC_TIMESTAMP() - INTERVAL 240 MINUTE),
(37, 8, 'sneakers', 'info', 'sacai-ldwaffle-blue', NULL, '사카이 LD와플 블루 멀티 재발매 루머가 있네요. 당분간 가격 약세 예상됩니다.', UTC_TIMESTAMP() - INTERVAL 2040 MINUTE, UTC_TIMESTAMP() - INTERVAL 2040 MINUTE),
(38, 1, 'sneakers', 'analysis', 'dunk-low-panda', NULL, '범고래는 재발매가 계속돼서 13만 원 아래로 내려왔네요. 실착용으로는 지금이 매수 타이밍 같습니다.', UTC_TIMESTAMP() - INTERVAL 1140 MINUTE, UTC_TIMESTAMP() - INTERVAL 1140 MINUTE),
(39, 8, 'sneakers', 'qna', 'dunk-low-grey-fog', NULL, '그레이 포그 vs 범고래, 실착용으로 뭐가 더 나을까요?', UTC_TIMESTAMP() - INTERVAL 600 MINUTE, UTC_TIMESTAMP() - INTERVAL 600 MINUTE),
(40, 9, 'watch', 'analysis', 'rolex-daytona-white', NULL, '데이토나 화이트 다이얼 시세가 조금씩 빠지고 있습니다. 4천만 원 초반까지 내려올 수도 있겠어요.', UTC_TIMESTAMP() - INTERVAL 1920 MINUTE, UTC_TIMESTAMP() - INTERVAL 1920 MINUTE),
(41, 9, 'watch', 'info', 'omega-speedmaster-moonwatch', NULL, '문워치 신형 사파이어 샌드위치 모델이 더 인기가 많습니다. 구매 시 레퍼런스 꼭 확인하세요.', UTC_TIMESTAMP() - INTERVAL 1500 MINUTE, UTC_TIMESTAMP() - INTERVAL 1500 MINUTE),
(42, 2, 'watch', 'qna', 'omega-speedmaster-moonwatch', NULL, '문워치 풀세트 920만 원이면 괜찮은 가격인가요?', UTC_TIMESTAMP() - INTERVAL 840 MINUTE, UTC_TIMESTAMP() - INTERVAL 840 MINUTE),
(43, 9, 'watch', 'analysis', 'rolex-submariner', NULL, '서브마리너는 아직 플랫폼 거래 이력이 없어서 해외 시세를 참고해야 합니다.', UTC_TIMESTAMP() - INTERVAL 1380 MINUTE, UTC_TIMESTAMP() - INTERVAL 1380 MINUTE),
(44, 9, 'watch', 'analysis', 'chanel-classic-flap-medium', NULL, '샤넬 클플 미디움은 가격 인상 이후 리셀가도 1,500만 원대 중반으로 따라 올랐습니다.', UTC_TIMESTAMP() - INTERVAL 1020 MINUTE, UTC_TIMESTAMP() - INTERVAL 1020 MINUTE),
(45, 3, 'watch', 'qna', 'lv-neverfull-mm', NULL, '네버풀 MM 중고 200만 원 초반이면 사도 될까요? 정품 감정은 어디서 받으시나요?', UTC_TIMESTAMP() - INTERVAL 780 MINUTE, UTC_TIMESTAMP() - INTERVAL 780 MINUTE),
(46, 4, 'pokemon', 'analysis', 'charizard-ex-sar-shiny-treasure-psa10', NULL, '샤이니트레저 리자몽 SAR은 한국판 151보다 저렴해서 입문용으로 좋아 보입니다.', UTC_TIMESTAMP() - INTERVAL 2280 MINUTE, UTC_TIMESTAMP() - INTERVAL 2280 MINUTE),
(47, 5, 'pokemon', 'qna', 'charizard-25th-promo-sealed', NULL, '25주년 프로모 리자몽 미개봉이면 그레이딩 없이 보관해도 괜찮을까요?', UTC_TIMESTAMP() - INTERVAL 1380 MINUTE, UTC_TIMESTAMP() - INTERVAL 1380 MINUTE),
(48, 6, 'pokemon', 'analysis', 'charizard-base-set-1st-shadowless-psa9', NULL, '초판 섀도리스 PSA9은 400만 원대 초반에서 거래가 이어지고 있습니다. 장기 우상향 종목.', UTC_TIMESTAMP() - INTERVAL 2220 MINUTE, UTC_TIMESTAMP() - INTERVAL 2220 MINUTE),
(49, 7, 'pokemon', 'verify', 'shiny-charizard-vmax-bgs95', NULL, 'BGS 9.5 서브그레이드 꼭 확인하세요. 센터링 9.5 이상이어야 프리미엄 붙습니다.', UTC_TIMESTAMP() - INTERVAL 900 MINUTE, UTC_TIMESTAMP() - INTERVAL 900 MINUTE),
(50, 4, 'pokemon', 'info', 'pokemon-151-booster-box-sealed', NULL, '151 부스터 박스 미개봉 재고가 줄고 있어요. 시세 19만 원대 유지 중입니다.', UTC_TIMESTAMP() - INTERVAL 480 MINUTE, UTC_TIMESTAMP() - INTERVAL 480 MINUTE),
(51, 5, 'free', 'qna', NULL, '리셀 입문자 질문드려요', '리셀 처음 시작하는데 안전거래 팁 공유 부탁드립니다!', UTC_TIMESTAMP() - INTERVAL 2820 MINUTE, UTC_TIMESTAMP() - INTERVAL 2820 MINUTE),
(52, 6, 'free', 'info', NULL, '최근 사기 수법 공유', '외부 계좌 입금 유도하는 사기 계정 조심하세요. 반드시 안심거래로 진행하세요.', UTC_TIMESTAMP() - INTERVAL 2460 MINUTE, UTC_TIMESTAMP() - INTERVAL 2460 MINUTE),
(53, 7, 'free', 'poll', NULL, '컬렉션 보관 방법 투표', '여러분은 어떤 방식으로 컬렉션을 보관하시나요?', UTC_TIMESTAMP() - INTERVAL 120 MINUTE, UTC_TIMESTAMP() - INTERVAL 120 MINUTE),
(54, 8, 'free', 'poll', NULL, '11월 발매 기대작 투표', '이번 달 가장 기대되는 발매는?', UTC_TIMESTAMP() - INTERVAL 9000 MINUTE, UTC_TIMESTAMP() - INTERVAL 9000 MINUTE),
(55, 9, 'free', 'info', NULL, '시계 리셀 체크리스트', '시계 거래 시 보증서·구매 영수증·박스 유무로 체결가가 10% 이상 차이납니다.', UTC_TIMESTAMP() - INTERVAL 60 MINUTE, UTC_TIMESTAMP() - INTERVAL 60 MINUTE),
(56, 1, 'free', 'analysis', NULL, '이번 주 리셀 시장 정리', '이번 주 전체적으로 카드 시세는 강세, 스니커즈는 약세 흐름이었습니다.', UTC_TIMESTAMP() - INTERVAL 30 MINUTE, UTC_TIMESTAMP() - INTERVAL 30 MINUTE);

