INSERT INTO comments (id, post_id, user_id, parent_id, body, created_at, updated_at, deleted_at) VALUES
(1, 1, 2, NULL, '저도 같은 생각이에요. 30만 원 아래로는 매물이 거의 안 보이네요.', UTC_TIMESTAMP() - INTERVAL 3312 MINUTE, UTC_TIMESTAMP() - INTERVAL 3312 MINUTE, NULL),
(2, 1, 1, 1, '맞아요. 특히 PSA10은 더 귀해졌어요.', UTC_TIMESTAMP() - INTERVAL 3222 MINUTE, UTC_TIMESTAMP() - INTERVAL 3222 MINUTE, NULL),
(3, 1, 3, 1, '그래도 신규 팩 재판 소식 나오면 흔들릴 수 있지 않을까요?', UTC_TIMESTAMP() - INTERVAL 3016 MINUTE, UTC_TIMESTAMP() - INTERVAL 3016 MINUTE, NULL),
(4, 1, 2, 1, '재판은 일본판 기준이라 한국판은 영향이 적을 것 같아요.', UTC_TIMESTAMP() - INTERVAL 2950 MINUTE, UTC_TIMESTAMP() - INTERVAL 2950 MINUTE, NULL),
(5, 1, 1, 1, '작년 재판 때도 한국판은 거의 안 빠졌어요.', UTC_TIMESTAMP() - INTERVAL 2802 MINUTE, UTC_TIMESTAMP() - INTERVAL 2802 MINUTE, NULL),
(6, 1, 3, 1, '좋은 정보 감사합니다!', UTC_TIMESTAMP() - INTERVAL 2751 MINUTE, UTC_TIMESTAMP() - INTERVAL 2751 MINUTE, NULL),
(7, 1, 3, NULL, '그레이딩 비용까지 생각하면 지금 가격도 비싸진 않은 것 같아요.', UTC_TIMESTAMP() - INTERVAL 2731 MINUTE, UTC_TIMESTAMP() - INTERVAL 2731 MINUTE, UTC_TIMESTAMP() - INTERVAL 2730 MINUTE),
(8, 1, 1, 7, '삭제하셨네요 ㅎㅎ 그래도 동의합니다.', UTC_TIMESTAMP() - INTERVAL 2715 MINUTE, UTC_TIMESTAMP() - INTERVAL 2715 MINUTE, NULL),
(9, 1, 3, NULL, '해외 시세도 같이 오르고 있어서 당분간은 버틸 듯합니다.', UTC_TIMESTAMP() - INTERVAL 2659 MINUTE, UTC_TIMESTAMP() - INTERVAL 2659 MINUTE, NULL),
(10, 1, 1, NULL, '저는 한 장 더 사두려고요.', UTC_TIMESTAMP() - INTERVAL 2274 MINUTE, UTC_TIMESTAMP() - INTERVAL 2274 MINUTE, NULL),
(11, 1, 2, 10, '어디서 사셨어요?', UTC_TIMESTAMP() - INTERVAL 1967 MINUTE, UTC_TIMESTAMP() - INTERVAL 1967 MINUTE, NULL),
(12, 1, 2, NULL, '센터링 좋은 개체는 프리미엄이 더 붙더라고요.', UTC_TIMESTAMP() - INTERVAL 1704 MINUTE, UTC_TIMESTAMP() - INTERVAL 1704 MINUTE, NULL),
(13, 1, 3, NULL, '최근 체결가 그래프 보면 우상향이 확실하네요.', UTC_TIMESTAMP() - INTERVAL 1662 MINUTE, UTC_TIMESTAMP() - INTERVAL 1662 MINUTE, NULL),
(14, 1, 1, NULL, '다음 달 대회 시즌 끝나면 조정 올 수도 있어요.', UTC_TIMESTAMP() - INTERVAL 1605 MINUTE, UTC_TIMESTAMP() - INTERVAL 1605 MINUTE, NULL),
(15, 1, 2, NULL, '대회랑 SAR 시세는 큰 상관 없지 않나요?', UTC_TIMESTAMP() - INTERVAL 1313 MINUTE, UTC_TIMESTAMP() - INTERVAL 1313 MINUTE, NULL),
(16, 1, 3, NULL, '컬렉터 수요가 꾸준해서 장기적으로는 괜찮다고 봅니다.', UTC_TIMESTAMP() - INTERVAL 1013 MINUTE, UTC_TIMESTAMP() - INTERVAL 1013 MINUTE, NULL),
(17, 1, 1, NULL, '실물 인증 사진 꼭 확인하고 사세요. 가품 슬랩도 돌아요.', UTC_TIMESTAMP() - INTERVAL 751 MINUTE, UTC_TIMESTAMP() - INTERVAL 751 MINUTE, NULL),
(18, 1, 2, NULL, '좋은 분석 감사합니다. 참고할게요!', UTC_TIMESTAMP() - INTERVAL 690 MINUTE, UTC_TIMESTAMP() - INTERVAL 690 MINUTE, NULL),
(19, 1, 3, NULL, '저는 반대로 지금이 고점이라 봐서 정리했어요.', UTC_TIMESTAMP() - INTERVAL 634 MINUTE, UTC_TIMESTAMP() - INTERVAL 634 MINUTE, NULL),
(20, 2, 1, NULL, '단기 고점일 수는 있는데 장기로 보면 괜찮을 것 같아요.', UTC_TIMESTAMP() - INTERVAL 1890 MINUTE, UTC_TIMESTAMP() - INTERVAL 1890 MINUTE, NULL),
(21, 2, 2, 20, '장기 보유 생각이면 사도 될까요?', UTC_TIMESTAMP() - INTERVAL 1557 MINUTE, UTC_TIMESTAMP() - INTERVAL 1557 MINUTE, NULL),
(22, 2, 1, 20, '네, 저라면 분할 매수하겠습니다.', UTC_TIMESTAMP() - INTERVAL 1490 MINUTE, UTC_TIMESTAMP() - INTERVAL 1490 MINUTE, NULL),
(23, 2, 3, NULL, '한 주 정도 지켜보고 사셔도 늦지 않아요.', UTC_TIMESTAMP() - INTERVAL 1410 MINUTE, UTC_TIMESTAMP() - INTERVAL 1410 MINUTE, NULL),
(24, 2, 1, NULL, '거래량이 같이 늘고 있어서 급락은 없을 듯합니다.', UTC_TIMESTAMP() - INTERVAL 1224 MINUTE, UTC_TIMESTAMP() - INTERVAL 1224 MINUTE, NULL),
(25, 3, 1, NULL, '저는 무조건 2015 OG요. 오리지널은 대체 불가죠.', UTC_TIMESTAMP() - INTERVAL 2345 MINUTE, UTC_TIMESTAMP() - INTERVAL 2345 MINUTE, NULL),
(26, 3, 2, NULL, '실착용이면 로스트앤파운드가 마음 편해요.', UTC_TIMESTAMP() - INTERVAL 2244 MINUTE, UTC_TIMESTAMP() - INTERVAL 2244 MINUTE, NULL),
(27, 3, 3, 26, '빈티지 박스 감성도 좋더라고요.', UTC_TIMESTAMP() - INTERVAL 1702 MINUTE, UTC_TIMESTAMP() - INTERVAL 1702 MINUTE, NULL),
(28, 5, 1, NULL, '한국판이 오를 때 일본판은 따라가지 못하는 흐름이네요.', UTC_TIMESTAMP() - INTERVAL 2930 MINUTE, UTC_TIMESTAMP() - INTERVAL 2930 MINUTE, NULL),
(29, 5, 2, 28, '네, 해외 물량이 계속 들어오는 게 큰 것 같아요.', UTC_TIMESTAMP() - INTERVAL 2926 MINUTE, UTC_TIMESTAMP() - INTERVAL 2926 MINUTE, NULL),
(30, 5, 3, 28, '그래도 PSA10 기준으로는 아직 일본판이 귀하지 않나요?', UTC_TIMESTAMP() - INTERVAL 2920 MINUTE, UTC_TIMESTAMP() - INTERVAL 2920 MINUTE, NULL),
(31, 5, 3, NULL, '28만 원대면 저는 매수 고려해 볼 만하다고 봅니다.', UTC_TIMESTAMP() - INTERVAL 2850 MINUTE, UTC_TIMESTAMP() - INTERVAL 2850 MINUTE, NULL),
(32, 5, 1, NULL, '체결가 그래프 보니 2주 전 31만 원이 고점이었네요.', UTC_TIMESTAMP() - INTERVAL 2741 MINUTE, UTC_TIMESTAMP() - INTERVAL 2741 MINUTE, NULL),
(33, 5, 2, 32, '맞아요. 그때 팔 걸 그랬습니다 ㅠ', UTC_TIMESTAMP() - INTERVAL 2350 MINUTE, UTC_TIMESTAMP() - INTERVAL 2350 MINUTE, NULL),
(34, 5, 2, NULL, '다음 주 재판 발표 전까지는 더 지켜보려고요.', UTC_TIMESTAMP() - INTERVAL 2170 MINUTE, UTC_TIMESTAMP() - INTERVAL 2170 MINUTE, UTC_TIMESTAMP() - INTERVAL 2169 MINUTE),
(35, 5, 3, 34, '재판 소식 있으면 공유 부탁드려요!', UTC_TIMESTAMP() - INTERVAL 2029 MINUTE, UTC_TIMESTAMP() - INTERVAL 2029 MINUTE, NULL),
(36, 6, 1, NULL, '장기 소장이면 한국판이 물량이 적어서 유리하다고 생각해요.', UTC_TIMESTAMP() - INTERVAL 2490 MINUTE, UTC_TIMESTAMP() - INTERVAL 2490 MINUTE, NULL),
(37, 6, 3, 36, '물량 차이가 그렇게 큰가요?', UTC_TIMESTAMP() - INTERVAL 2377 MINUTE, UTC_TIMESTAMP() - INTERVAL 2377 MINUTE, NULL),
(38, 6, 1, 36, '한국판 SV2a는 초판 이후 재판이 거의 없었어요.', UTC_TIMESTAMP() - INTERVAL 1978 MINUTE, UTC_TIMESTAMP() - INTERVAL 1978 MINUTE, NULL),
(39, 6, 2, NULL, '해외 판매까지 생각하면 일본판이 거래하기 편합니다.', UTC_TIMESTAMP() - INTERVAL 1861 MINUTE, UTC_TIMESTAMP() - INTERVAL 1861 MINUTE, NULL),
(40, 6, 1, NULL, '둘 다 PSA10이면 결국 개체 상태가 더 중요하더라고요.', UTC_TIMESTAMP() - INTERVAL 1779 MINUTE, UTC_TIMESTAMP() - INTERVAL 1779 MINUTE, NULL),
(41, 7, 2, NULL, '정보 감사합니다! 이번 달에 꼭 보내야겠네요.', UTC_TIMESTAMP() - INTERVAL 2072 MINUTE, UTC_TIMESTAMP() - INTERVAL 2072 MINUTE, NULL),
(42, 8, 2, NULL, '부스터 발매 일정 나오면 다시 움직일 것 같아요.', UTC_TIMESTAMP() - INTERVAL 1839 MINUTE, UTC_TIMESTAMP() - INTERVAL 1839 MINUTE, NULL),
